'use client';

import { AnimatePresence } from 'motion/react';
import { useRef } from 'react';

import { cn } from '@/registry/ndeko/lib/utils';
import { DrawnCheck } from '@/registry/ndeko/ui/drawn-check';

import type { Loop } from './_parts/loops';
import {
  ThinkingDemo,
  type IndicatorState,
  type ThinkingDemoAgent,
} from './_parts/thinking-demo';
import {
  DEFAULT_LABEL,
  MARK_BOX,
  ThinkingStatus,
  type ThinkingIndicatorProps,
  type ThinkingSize,
} from './_parts/thinking-status';
import { useLoopGate, useLoops } from './_parts/use-loops';

/** How tall each bar grows at the top of its swell, from its resting pill: the middle one most. */
const PEAKS = [2.3, 2.9, 3.1, 2.8, 2.2];

/** Under reduced motion the wave rests on one moment of its swell. */
const STILL_SCALES = [1.5, 2.6, 3.1, 2.1, 1.3];

const SWELL_MS = 1150;

const BAR_STEP_MS = 120;

const RISE_EASING = 'cubic-bezier(0.33, 0, 0.2, 1)';

const FALL_EASING = 'cubic-bezier(0.45, 0, 0.55, 1)';

const BARS = PEAKS.map((_, index) => index);

const REST = 'scaleY(1)';

function swellKeyframesOf(peak: number): Keyframe[] {
  return [
    { transform: REST, offset: 0, easing: RISE_EASING },
    { transform: `scaleY(${peak})`, offset: 0.3, easing: FALL_EASING },
    { transform: REST, offset: 0.68 },
    { transform: REST, offset: 1 },
  ];
}

/** The bars rise and fall one after the other, from the first to the last, then breathe out together. */
function swellLoopsOf(root: HTMLElement): Loop[] {
  const bars = Array.from(root.querySelectorAll('[data-bar]'));
  return bars.map((element, index) => ({
    element,
    keyframes: swellKeyframesOf(PEAKS[index] ?? 1),
    timing: {
      duration: SWELL_MS,
      delay: index * BAR_STEP_MS,
      iterations: Infinity,
    },
  }));
}

function barStyleOf(index: number, showsStill: boolean) {
  if (!showsStill) {
    return { transform: REST };
  }
  const scale = STILL_SCALES[index] ?? 1;
  return { transform: `scaleY(${scale})` };
}

function barsLayerOf(isDone: boolean) {
  if (isDone) {
    return 'opacity-0 duration-150';
  }
  return 'opacity-100 duration-200';
}

type WaveMarkProps = {
  size: ThinkingSize;
  isDone: boolean;
  canLoop: boolean;
  isPlaying: boolean;
  isStill: boolean;
};

function WaveMark({
  size,
  isDone,
  canLoop,
  isPlaying,
  isStill,
}: WaveMarkProps) {
  const barsRef = useRef<HTMLSpanElement>(null);
  const showsStill = isStill && !isDone;

  useLoops(barsRef, { canLoop, isPlaying, create: swellLoopsOf });

  return (
    <span
      aria-hidden='true'
      className={cn(
        'relative grid shrink-0 place-items-center',
        MARK_BOX[size]
      )}
    >
      <span
        ref={barsRef}
        className={cn(
          'absolute inset-0 flex items-center justify-between transition-opacity ease-(--ease-out-strong)',
          barsLayerOf(isDone)
        )}
      >
        {BARS.map((index) => (
          <span
            key={index}
            data-bar=''
            style={barStyleOf(index, showsStill)}
            className='bg-primary h-[32%] w-[13%] rounded-full'
          />
        ))}
      </span>
      <AnimatePresence initial={false}>
        {isDone && (
          <DrawnCheck key='done' tone='success' className='size-full' />
        )}
      </AnimatePresence>
    </span>
  );
}

type ThinkingWaveProps = ThinkingIndicatorProps & {
  /** Only the wave, for a header or a button; the label is still read by screen readers. */
  isCompact?: boolean;
};

/**
 * A thinking status: five rounded bars swell one after the other, a small wave that breathes,
 * beside a label a soft light passes over. When the work is done the bars settle and a check
 * draws itself in their place.
 */
export function ThinkingWave({
  label = DEFAULT_LABEL,
  size = 'md',
  isDone = false,
  isCompact = false,
  className,
}: ThinkingWaveProps) {
  const { ref, canLoop, isPlaying, isStill } = useLoopGate(!isDone);

  return (
    <ThinkingStatus
      ref={ref}
      label={label}
      size={size}
      isDone={isDone}
      canLoop={canLoop}
      isPlaying={isPlaying}
      showsLabel={!isCompact}
      className={className}
    >
      <WaveMark
        size={size}
        isDone={isDone}
        canLoop={canLoop}
        isPlaying={isPlaying}
        isStill={isStill}
      />
    </ThinkingStatus>
  );
}

const AGENT: ThinkingDemoAgent = { name: 'Writer', series: 2 };

const STEPS = ['Thinking', 'Reading the thread', 'Drafting a reply'];

function renderWave({ label, isDone }: IndicatorState) {
  return <ThinkingWave label={label} isDone={isDone} size='lg' />;
}

/** The compact wave after the agent's name, as a list of conversations would show it. */
function renderCompactWave({ label, isDone }: IndicatorState) {
  return (
    <span aria-hidden='true' className='flex'>
      <ThinkingWave label={label} isDone={isDone} size='sm' isCompact />
    </span>
  );
}

export default function Loading02() {
  return (
    <ThinkingDemo
      agent={AGENT}
      steps={STEPS}
      doneLabel='Reply ready'
      renderIndicator={renderWave}
      renderBesideName={renderCompactWave}
    />
  );
}

export type Loop = {
  element: Element;
  keyframes: Keyframe[];
  timing: KeyframeAnimationOptions;
};

const LAND_MS = 220;

const LAND_EASING = 'cubic-bezier(0.23, 1, 0.32, 1)';

/**
 * Each loop runs in the browser's own animation engine on transform and opacity only, so the
 * compositor plays it and the page does no work per frame.
 */
export function startLoops(loops: readonly Loop[]) {
  return loops.map((loop) => loop.element.animate(loop.keyframes, loop.timing));
}

/**
 * A cancelled animation is left alone: playing or even pausing it would bring it back and hold its
 * element in a pose its mark has already left.
 */
function isCancelled(animation: Animation) {
  return animation.playState === 'idle';
}

export function playAll(animations: readonly Animation[]) {
  for (const animation of animations) {
    if (!isCancelled(animation)) {
      animation.play();
    }
  }
}

export function pauseAll(animations: readonly Animation[]) {
  for (const animation of animations) {
    if (!isCancelled(animation)) {
      animation.pause();
    }
  }
}

export function cancelAll(animations: readonly Animation[]) {
  for (const animation of animations) {
    animation.cancel();
  }
}

function targetOf(animation: Animation) {
  const effect = animation.effect;
  if (effect instanceof KeyframeEffect) {
    return effect.target;
  }
  return null;
}

function poseOf(element: Element): Keyframe {
  const styles = getComputedStyle(element);
  return { transform: styles.transform, opacity: styles.opacity };
}

/** From the pose its loop left it in, an element glides back to its own resting style, then lets go. */
function land(animation: Animation) {
  const target = targetOf(animation);
  if (!target?.isConnected) {
    animation.cancel();
    return;
  }
  const shown = poseOf(target);
  animation.cancel();
  const rest = poseOf(target);
  target.animate([shown, rest], { duration: LAND_MS, easing: LAND_EASING });
}

export function landAll(animations: readonly Animation[]) {
  for (const animation of animations) {
    land(animation);
  }
}

'use client';

import { AnimatePresence, motion, type Transition } from 'motion/react';
import { Fragment, useRef } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { EASE_OUT_STRONG } from '@/registry/ndeko/lib/motion-presets';
import { cn } from '@/registry/ndeko/lib/utils';
import { leadingSpaceOf, wordsOf } from '@/registry/ndeko/lib/words';

import type { Loop } from './loops';
import { useLoops } from './use-loops';

const LETTER_STEP_MS = 70;

const GLINT_RISE_MS = 140;

const GLINT_FALL_MS = 260;

/** How far the light lifts a letter towards the text colour: a soft shimmer, short of a flash. */
const GLINT_PEAK = 0.85;

const PASS_REST_MS = 900;

const SINE_EASING = 'cubic-bezier(0.37, 0, 0.63, 1)';

const ENTER: Transition = { duration: 0.2, ease: EASE_OUT_STRONG };

const EXIT: Transition = { duration: 0.12, ease: EASE_OUT_STRONG };

const ARRIVING = { opacity: 0, y: 4, filter: 'blur(2px)' };

const SHOWN = { opacity: 1, y: 0, filter: 'blur(0px)', transition: ENTER };

const LEAVING = { opacity: 0, y: -4, filter: 'blur(2px)', transition: EXIT };

const FADING_IN = { opacity: 0 };

const FADED_IN = { opacity: 1, transition: ENTER };

const FADING_OUT = { opacity: 0, transition: EXIT };

function presenceOf(shouldReduceMotion: boolean) {
  if (shouldReduceMotion) {
    return { initial: FADING_IN, animate: FADED_IN, exit: FADING_OUT };
  }
  return { initial: ARRIVING, animate: SHOWN, exit: LEAVING };
}

function periodOf(letterCount: number) {
  const sweep = letterCount * LETTER_STEP_MS;
  const glint = GLINT_RISE_MS + GLINT_FALL_MS;
  return sweep + glint + PASS_REST_MS;
}

function glintKeyframesOf(periodMs: number): Keyframe[] {
  const litAt = GLINT_RISE_MS / periodMs;
  const goneAt = (GLINT_RISE_MS + GLINT_FALL_MS) / periodMs;
  return [
    { opacity: 0, offset: 0, easing: SINE_EASING },
    { opacity: GLINT_PEAK, offset: litAt, easing: SINE_EASING },
    { opacity: 0, offset: goneAt },
    { opacity: 0, offset: 1 },
  ];
}

/** A soft light passes over the letters one after the other: each one brightens towards the text colour and fades back. */
function glintLoopsOf(root: HTMLElement): Loop[] {
  const glints = Array.from(root.querySelectorAll('[data-glint]'));
  const periodMs = periodOf(glints.length);
  const keyframes = glintKeyframesOf(periodMs);
  return glints.map((element, index) => ({
    element,
    keyframes,
    timing: {
      duration: periodMs,
      delay: index * LETTER_STEP_MS,
      iterations: Infinity,
    },
  }));
}

type WordProps = {
  word: string;
};

/** A word never breaks inside itself; each letter carries its own light over it. */
function Word({ word }: WordProps) {
  const letters = Array.from(word);
  return (
    <span className='whitespace-nowrap'>
      {letters.map((letter, index) => (
        <span key={index} className='relative inline-block'>
          {letter}
          <span
            data-glint=''
            className='text-foreground pointer-events-none absolute inset-0 opacity-0 select-none'
          >
            {letter}
          </span>
        </span>
      ))}
    </span>
  );
}

type ShimmerTextProps = {
  text: string;
  canLoop: boolean;
  isPlaying: boolean;
};

function ShimmerText({ text, canLoop, isPlaying }: ShimmerTextProps) {
  const ref = useRef<HTMLSpanElement>(null);
  const words = wordsOf(text);

  useLoops(ref, { canLoop, isPlaying, create: glintLoopsOf });

  return (
    <span ref={ref} className='block'>
      {words.map((word, index) => (
        <Fragment key={index}>
          {leadingSpaceOf(index)}
          <Word word={word} />
        </Fragment>
      ))}
    </span>
  );
}

function toneOf(isDone: boolean) {
  if (isDone) {
    return 'text-foreground';
  }
  return 'text-muted-foreground';
}

type ShimmerLabelProps = {
  text: string;
  isDone: boolean;
  canLoop: boolean;
  isPlaying: boolean;
  className?: string;
};

/**
 * The words of a status, muted while the work runs, with a light that passes over them letter by
 * letter (opacity only), and in the text colour once it is done. A new label rises in as the old
 * one leaves. The words are drawn for the eye: the status that holds them says them once.
 */
export function ShimmerLabel({
  text,
  isDone,
  canLoop,
  isPlaying,
  className,
}: ShimmerLabelProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const presence = presenceOf(shouldReduceMotion);

  return (
    <span
      aria-hidden='true'
      className={cn(
        'relative block min-w-0 transition-colors duration-200',
        toneOf(isDone),
        className
      )}
    >
      <AnimatePresence mode='popLayout' initial={false}>
        <motion.span key={text} className='block' {...presence}>
          <ShimmerText text={text} canLoop={canLoop} isPlaying={isPlaying} />
        </motion.span>
      </AnimatePresence>
    </span>
  );
}

'use client';

import { useState, type ReactNode } from 'react';

import {
  useAutoplay,
  type AutoplayStep,
} from '@/registry/ndeko/hooks/use-autoplay';
import { useKeptHeight } from '@/registry/ndeko/hooks/use-kept-height';
import { seriesColorOf, type SeriesSlot } from '@/registry/ndeko/lib/agent-run';
import { hiddenIf } from '@/registry/ndeko/lib/demonstration';
import { MeshTile } from '@/registry/ndeko/ui/mesh-tile';
import { Segments, type Segment } from '@/registry/ndeko/ui/segments';

type Phase = 'thinking' | 'done';

const PHASES: Segment<Phase>[] = [
  { value: 'thinking', label: 'Thinking' },
  { value: 'done', label: 'Done' },
];

const LABEL_HOLD_MS = 1800;

const DONE_HOLD_MS = 2400;

export type ThinkingDemoAgent = {
  name: string;
  series: SeriesSlot;
};

export type IndicatorState = {
  label: string;
  isDone: boolean;
};

type ThinkingDemoProps = {
  agent: ThinkingDemoAgent;
  /** The labels the work goes through; the first one shows when it starts. */
  steps: readonly string[];
  doneLabel: string;
  renderIndicator: (state: IndicatorState) => ReactNode;
  /** A second mark after the agent's name, for a variant shown in a header. */
  renderBesideName?: (state: IndicatorState) => ReactNode;
};

function phaseOf(isDone: boolean): Phase {
  if (isDone) {
    return 'done';
  }
  return 'thinking';
}

function labelOf(
  steps: readonly string[],
  stepIndex: number,
  isDone: boolean,
  doneLabel: string
) {
  if (isDone) {
    return doneLabel;
  }
  return steps[stepIndex] ?? '';
}

/**
 * An agent's turn in a conversation: its name, then its status. The demonstration walks the work
 * through its labels, lands it on done, holds, and starts again; the switch under the card lets a
 * person do the same.
 */
export function ThinkingDemo({
  agent,
  steps,
  doneLabel,
  renderIndicator,
  renderBesideName,
}: ThinkingDemoProps) {
  const [stepIndex, setStepIndex] = useState(0);
  const [isDone, setIsDone] = useState(false);
  const label = labelOf(steps, stepIndex, isDone, doneLabel);
  const state: IndicatorState = { label, isDone };

  function startOver() {
    setStepIndex(0);
    setIsDone(false);
  }

  function choose(phase: Phase) {
    if (phase === 'done') {
      setIsDone(true);
      return;
    }
    startOver();
  }

  const nextLabels: AutoplayStep[] = steps.slice(1).map((_, index) => ({
    after: LABEL_HOLD_MS,
    run: () => setStepIndex(index + 1),
  }));
  const autoplaySteps: AutoplayStep[] = [
    ...nextLabels,
    { after: LABEL_HOLD_MS, run: () => setIsDone(true) },
  ];
  const { ref, isAutoplaying } = useAutoplay(autoplaySteps, {
    loopAfter: DONE_HOLD_MS,
    onReset: startOver,
  });

  useKeptHeight(ref);

  return (
    <div
      ref={ref}
      className='flex w-full max-w-[22rem] flex-col items-center gap-3'
    >
      <div className='bg-card hairline-ring ring-border flex w-full flex-col gap-2 rounded-xl p-4 shadow-[0_1px_2px_rgb(0_0_0/0.04)]'>
        <div className='flex min-w-0 items-center gap-2'>
          <MeshTile seed={agent.name} color={seriesColorOf(agent.series)} />
          <p className='min-w-0 truncate text-[13px] font-medium'>
            {agent.name}
          </p>
          {renderBesideName?.(state)}
        </div>
        <div aria-hidden={hiddenIf(isAutoplaying)} className='min-w-0 ps-7'>
          {renderIndicator(state)}
        </div>
      </div>
      <Segments
        value={phaseOf(isDone)}
        segments={PHASES}
        onValueChange={choose}
        label='Indicator state'
        className='w-full max-w-[13rem]'
      />
    </div>
  );
}

'use client';

import type { ReactNode, Ref } from 'react';

import { cn } from '@/registry/ndeko/lib/utils';

import { ShimmerLabel } from './shimmer-label';

export type ThinkingSize = 'sm' | 'md' | 'lg';

export type ThinkingIndicatorProps = {
  /** What the agent is doing, beside the mark and read by screen readers: Thinking, Reading the brief. */
  label?: string;
  /** `sm` sits in a line of small text, `md` in a message, `lg` alone. */
  size?: ThinkingSize;
  /** The work is over: the mark lands on its done state and the label stops shimmering. */
  isDone?: boolean;
  className?: string;
};

export const DEFAULT_LABEL = 'Thinking';

/** The mark is as tall as one line of its label, so a label that wraps keeps the mark on its first line. */
export const MARK_BOX: Record<ThinkingSize, string> = {
  sm: 'size-4',
  md: 'size-5',
  lg: 'size-6',
};

const LABEL_TYPE: Record<ThinkingSize, string> = {
  sm: 'text-xs leading-4',
  md: 'text-[13px] leading-5',
  lg: 'text-sm leading-6',
};

const ROW_GAP: Record<ThinkingSize, string> = {
  sm: 'gap-1.5',
  md: 'gap-2',
  lg: 'gap-2.5',
};

type ThinkingStatusProps = {
  ref: Ref<HTMLSpanElement>;
  label: string;
  size: ThinkingSize;
  isDone: boolean;
  canLoop: boolean;
  isPlaying: boolean;
  /** False for a mark shown alone: the label is still read by screen readers. */
  showsLabel?: boolean;
  className?: string;
  /** The mark, hidden from screen readers. */
  children: ReactNode;
};

/** A mark and its label in one status, so a change of label or the end of the work is said once. */
export function ThinkingStatus({
  ref,
  label,
  size,
  isDone,
  canLoop,
  isPlaying,
  showsLabel = true,
  className,
  children,
}: ThinkingStatusProps) {
  return (
    <span
      ref={ref}
      role='status'
      className={cn(
        'inline-flex max-w-full min-w-0 items-start align-top',
        ROW_GAP[size],
        className
      )}
    >
      {children}
      <span className='sr-only'>{label}</span>
      {showsLabel && (
        <ShimmerLabel
          text={label}
          isDone={isDone}
          canLoop={canLoop}
          isPlaying={isPlaying}
          className={LABEL_TYPE[size]}
        />
      )}
    </span>
  );
}

'use client';

import { useInView } from 'motion/react';
import { useEffect, useEffectEvent, useRef, type RefObject } from 'react';

import { useDocumentVisible } from '@/registry/ndeko/hooks/use-agent-run';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';

import {
  cancelAll,
  landAll,
  pauseAll,
  playAll,
  startLoops,
  type Loop,
} from './loops';

/**
 * Whether an indicator may loop and whether it plays right now. It loops while it runs and the
 * reduced motion setting is off; it plays only while it is on screen in the tab that is shown.
 */
export function useLoopGate<Root extends HTMLElement = HTMLSpanElement>(
  isRunning: boolean
) {
  const ref = useRef<Root>(null);
  const isInView = useInView(ref);
  const isTabVisible = useDocumentVisible();
  const isStill = usePrefersReducedMotion();
  const canLoop = isRunning && !isStill;
  const isOnScreen = isInView && isTabVisible;
  const isPlaying = canLoop && isOnScreen;

  return { ref, canLoop, isPlaying, isStill };
}

type LoopsOptions<Root> = {
  canLoop: boolean;
  isPlaying: boolean;
  create: (root: Root) => Loop[];
};

/**
 * The loops of a mark, made when it starts running and paused whenever it is not seen, so they ask
 * for no frame off screen or in a hidden tab. When it stops running each element glides back to
 * its resting style and the loops are gone, so a finished mark costs nothing.
 */
export function useLoops<Root extends HTMLElement>(
  rootRef: RefObject<Root | null>,
  { canLoop, isPlaying, create }: LoopsOptions<Root>
) {
  const running = useRef<Animation[] | null>(null);
  const isStill = usePrefersReducedMotion();

  const loopsOf = useEffectEvent((root: Root) => {
    const loops = create(root);
    return startLoops(loops);
  });

  /** Stopped by the reduced motion setting, a mark goes straight to rest instead of gliding there. */
  const finish = useEffectEvent((animations: Animation[], root: Root) => {
    const canGlide = root.isConnected && !isStill;
    if (canGlide) {
      landAll(animations);
      return;
    }
    cancelAll(animations);
  });

  useEffect(() => {
    const root = rootRef.current;
    if (!root || !canLoop) {
      return;
    }
    const animations = loopsOf(root);
    pauseAll(animations);
    running.current = animations;
    return () => {
      running.current = null;
      finish(animations, root);
    };
  }, [rootRef, canLoop]);

  useEffect(() => {
    const animations = running.current;
    if (!animations || !isPlaying) {
      return;
    }
    playAll(animations);
    return () => pauseAll(animations);
  }, [canLoop, isPlaying]);
}
